create extension if not exists "uuid-ossp";
create table if not exists public.books (id uuid primary key default uuid_generate_v4(), title text not null, author text not null, description text, cover_url text, pages int default 0, tags text[] default '{}', chapters jsonb default '[]', quotes text[] default '{}', created_at timestamptz default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz default now());
create table if not exists public.user_books (user_id uuid references auth.users(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, is_favorite boolean default false, progress numeric default 0 check(progress between 0 and 1), last_read_at timestamptz, primary key(user_id,book_id));
create table if not exists public.reviews (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, rating int not null check(rating between 1 and 5), body text, created_at timestamptz default now(), unique(user_id,book_id));
create table if not exists public.highlights (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, content text not null, note text, position int, created_at timestamptz default now());
create table if not exists public.collections (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, name text not null, created_at timestamptz default now());
create table if not exists public.collection_books (collection_id uuid references public.collections(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, primary key(collection_id,book_id));
create table if not exists public.notifications (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz default now());
alter table public.books enable row level security; alter table public.profiles enable row level security; alter table public.user_books enable row level security; alter table public.reviews enable row level security; alter table public.highlights enable row level security;
create policy "books readable" on public.books for select using (true); create policy "profile owner" on public.profiles for all using (auth.uid()=id); create policy "user books owner" on public.user_books for all using (auth.uid()=user_id); create policy "reviews readable" on public.reviews for select using (true); create policy "reviews owner write" on public.reviews for all using (auth.uid()=user_id); create policy "highlights owner" on public.highlights for all using (auth.uid()=user_id);
create index if not exists books_tags_idx on public.books using gin(tags); create index if not exists user_books_progress_idx on public.user_books(user_id,last_read_at);
